const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define the Northern Hemisphere as a bounding box.
  const northernHemisphere = ee.Geometry.Polygon(
      [[[-180, 0], [180, 0], [180, 90], [-180, 90]]], null, false
  );
  const startDate2019 = '2019-01-01';
  const endDate2019 = '2019-12-31';
  const startDate2020 = '2020-01-01';
  const endDate2020 = '2020-12-31';
  const band = 'NO2_column_number_density';

  // Function to mask low-quality pixels based on Sentinel-5P QA value.
  function maskLowQuality(image) {
    return image.updateMask(image.select('qa_value').gt(0.75));
  }

  // 2. Data Acquisition & Check
  const collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
                       .select([band, 'qa_value']);

  const col2019 = collection.filterDate(startDate2019, endDate2019);
  const col2020 = collection.filterDate(startDate2020, endDate2020);

  const size2019 = col2019.size().getInfo();
  const size2020 = col2020.size().getInfo();

  if (size2019 === 0 || size2020 === 0) {
    console.log(`Image count 2019: ${size2019}`);
    console.log(`Image count 2020: ${size2020}`);
    console.log("C1: Empty Collection");
    return;
  }
  console.log(`Image count 2019: ${size2019}`);
  console.log(`Image count 2020: ${size2020}`);

  // 3. Processing
  const mean2019 = col2019.map(maskLowQuality).select(band).mean();
  const mean2020 = col2020.map(maskLowQuality).select(band).mean();

  const options = {
      reducer: ee.Reducer.mean(),
      geometry: northernHemisphere,
      scale: 30000, // Use a coarse scale for a large area to avoid timeout
      maxPixels: 1e12
  };

  // 4. Calculation
  const stats2019 = mean2019.reduceRegion(options).get(band).getInfo();
  const stats2020 = mean2020.reduceRegion(options).get(band).getInfo();

  // 5. Validation & Final Answer
  if (stats2019 === null || stats2020 === null) {
      console.log(`2019 Result: ${stats2019}`);
      console.log(`2020 Result: ${stats2020}`);
      console.log("C3: Calculation Failure");
      return;
  }

  // S5P NO2 units are mol/m^2. It's a small number, so use scientific notation for clarity.
  console.log(`2019 Mean NO2: ${stats2019.toExponential(4)} mol/m^2`);
  console.log(`2020 Mean NO2: ${stats2020.toExponential(4)} mol/m^2`);

  if (stats2020 > stats2019) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error("An error occurred during analysis.");
    console.error(err);
    console.log("D");
});
